<?php
/**
 * Haster-Haken-Logo als Inline-SVG (Bildmarke „gestapelte Ordnung“ und
 * Schriftzug in Bricolage Grotesque ExtraBold, in Kurven).
 *
 * Farben kommen aus der Palette (primary = Achse und Schrift, accent-1 =
 * Module) – Änderungen unter Design → Lindenweg16 → Farben wirken mit.
 * Die Animation steht in theme.css (.lw16-hh).
 *
 * @package Lindenweg16
 */

declare( strict_types = 1 );

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Markup des Logos.
 *
 * @param bool   $wordmark Schriftzug unter der Marke zeigen.
 * @param string $label    Zugänglicher Name.
 */
function lindenweg16_haster_logo_svg( bool $wordmark = true, string $label = '' ): string {
	$label = '' !== $label ? $label : __( 'Haster Haken', 'lindenweg16' );
	$mark  = '<rect class="lw16-hh__axis" x="47" y="8" width="6" height="84" rx="3"/>'
		. '<rect class="lw16-hh__mod lw16-hh__mod--1" x="22" y="18" width="40" height="16" rx="8"/>'
		. '<rect class="lw16-hh__mod lw16-hh__mod--2" x="38" y="42" width="40" height="16" rx="8"/>'
		. '<rect class="lw16-hh__mod lw16-hh__mod--3" x="26" y="66" width="40" height="16" rx="8"/>';

	if ( ! $wordmark ) {
		return '<svg class="lw16-hh lw16-hh--mark" viewBox="0 0 100 100" role="img" aria-label="' . esc_attr( $label ) . '">' . $mark . '</svg>';
	}

	// Schriftzug halb so groß (Breite 205) mittig unter der 100×100-Marke – dieselben Proportionen wie im Video.
	return '<svg class="lw16-hh lw16-hh--logo" viewBox="0 0 210 146" role="img" aria-label="' . esc_attr( $label ) . '">'
		. '<g transform="translate(55 0)">' . $mark . '</g>'
		. '<g transform="translate(2.5 140) scale(0.5)"><path class="lw16-hh__word" d="' . LINDENWEG16_HASTER_WORDMARK . '"/></g>'
		. '</svg>';
}

